// D-M1, live: what the app records for timed exercises and what the backend
// computes from it (exercise completion, session completion). Skipped unless
// KORA_LIVE_API_BASE_URL is set; synthetic account whose current plan has timed
// exercises (generated by the rules engine, no Replicate).
//
//   KORA_LIVE_API_BASE_URL=http://localhost:8080/api/v1 KORA_LIVE_EMAIL_A=... KORA_LIVE_PASSWORD=... \
//   flutter test test/live/timed_exercise_live_test.dart
//
// Uses the app's real WorkoutRepository and prescribedResult («Lo completé»).
import 'dart:io';
import 'package:dio/dio.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:fitsense_mobile/core/api/json.dart';
import 'package:fitsense_mobile/features/workouts/data/workout_repository.dart';
import 'package:fitsense_mobile/features/workouts/domain/workout_rules.dart';

final env = Platform.environment;
final base = env['KORA_LIVE_API_BASE_URL'];

void main() {
  late Dio dio;
  late WorkoutRepository workouts;
  late List<Json> plan;

  setUpAll(() async {
    if (base == null) return;
    final login = await Dio(BaseOptions(baseUrl: base!)).post('/auth/login', data: {'email': env['KORA_LIVE_EMAIL_A'], 'password': env['KORA_LIVE_PASSWORD']});
    dio = Dio(BaseOptions(baseUrl: base!, contentType: Headers.jsonContentType, headers: {'Authorization': 'Bearer ${login.data['token']}'}));
    workouts = WorkoutRepository(dio);
    plan = jsonRows((await dio.get('/users/me/plan/current')).data['workouts']);
  });

  Json exerciseOf(Json session, Object id) => jsonRows(session['exercises']).firstWhere((e) => e['plannedExerciseId'] == id);
  double pct(Json e) => (e['completionPercentage'] as num).toDouble();
  List<Json> exercises(Json w) => jsonRows(w['exercises']);
  bool timed(Json e) => e['prescriptionType'] == 'DURATION';

  /// Open workouts (not expired), with timed exercises, in plan order.
  List<Json> live() => plan.where((w) => canStartWorkout(w) && exercises(w).any(timed)).toList();

  test('complete session: «Lo completé» on a timed exercise is 100 %, the one-series value of main was 33 %', () async {
    final workout = live().first;
    final session = await workouts.start(workout['plannedWorkoutId']);
    final target = exercises(workout).firstWhere(timed);
    final sets = (target['plannedSets'] as num).toInt(), perSet = (target['plannedDurationSeconds'] as num).toInt();
    expect(sets, greaterThan(1), reason: 'needs a multi-series timed exercise');

    // What main sent: the seconds of ONE series.
    final oneSeries = await workouts.record(session['sessionId'], target['plannedExerciseId'],
        {...prescribedResult(target), 'actualDurationSeconds': perSet});
    final wrong = exerciseOf(oneSeries, target['plannedExerciseId']);
    expect(pct(wrong), closeTo(100 / sets, 0.01));
    expect(wrong['status'], 'PARTIAL');

    // What the app sends now: every series (replaces the previous result).
    var current = oneSeries;
    for (final e in exercises(workout)) {
      current = await workouts.record(session['sessionId'], e['plannedExerciseId'], prescribedResult(e));
    }
    final right = exerciseOf(current, target['plannedExerciseId']);
    expect(right['actualDurationSeconds'], sets * perSet);
    expect(pct(right), 100);
    expect(right['status'], 'COMPLETED');

    final finished = await workouts.finish(session['sessionId'], {'sessionRpe': 6, 'activeMinutes': 40});
    expect((finished['completionPercentage'] as num).toDouble(), 100);
    expect(finished['status'], 'COMPLETED');
    // ignore: avoid_print
    print('COMPLETA workout=${workout['plannedWorkoutId']} ejercicio=${target['plannedExerciseId']} ${sets}x$perSet s: '
        'una serie (${perSet}s) → ${pct(wrong)} % ${wrong['status']}; todas (${sets * perSet}s) → ${pct(right)} % ${right['status']}; '
        'sesión ${finished['completionPercentage']} % ${finished['status']}');
  }, skip: base == null ? 'KORA_LIVE_API_BASE_URL not set (needs a running backend)' : false);

  test('partial session: only the seconds really done count; the session is the mean the backend computes', () async {
    final workout = live().last;
    final session = await workouts.start(workout['plannedWorkoutId']);
    final target = exercises(workout).firstWhere(timed);
    final total = plannedTotal(target);
    final done = total ~/ 2 + 15;
    Json current = session;
    for (final e in exercises(workout)) {
      final body = e['plannedExerciseId'] == target['plannedExerciseId']
          ? {'actualSets': 2, 'actualRepsTotal': 0, 'actualDurationSeconds': done, 'actualLoadKg': null, 'skipReason': 'FATIGUE'}
          : prescribedResult(e);
      current = await workouts.record(session['sessionId'], e['plannedExerciseId'], body);
    }
    final partial = exerciseOf(current, target['plannedExerciseId']);
    expect(partial['actualDurationSeconds'], done);
    expect(pct(partial), closeTo(done * 100 / total, 0.01), reason: 'no unexecuted time attributed');
    expect(partial['status'], 'PARTIAL');

    final finished = await workouts.finish(session['sessionId'], {'sessionRpe': 7, 'activeMinutes': 35});
    final rows = jsonRows(finished['exercises']);
    final mean = rows.map(pct).reduce((a, b) => a + b) / exercises(workout).length;
    expect((finished['completionPercentage'] as num).toDouble(), closeTo(mean, 0.01));
    expect(finished['completionPercentage'], lessThan(100));
    // ignore: avoid_print
    print('PARCIAL workout=${workout['plannedWorkoutId']} ejercicio=${target['plannedExerciseId']}: $done/$total s → ${pct(partial)} % ${partial['status']}; '
        'sesión ${finished['completionPercentage']} % ${finished['status']} (media de ${rows.length} ejercicios = ${mean.toStringAsFixed(2)} %)');
  }, skip: base == null ? 'KORA_LIVE_API_BASE_URL not set (needs a running backend)' : false);

  test('whole workout report («Ya lo hice»): «Lo completé» on every exercise is 100 %', () async {
    // A reportable workout with timed exercises not used by the two sessions above.
    final used = {live().first['plannedWorkoutId'], live().last['plannedWorkoutId']};
    final workout = plan.firstWhere((w) => canReportWorkout(w) && !used.contains(w['plannedWorkoutId']) && exercises(w).any(timed),
        orElse: () => <String, dynamic>{});
    if (workout.isEmpty) return markTestSkipped('no third workout with timed exercises in this plan');
    final reported = await workouts.report(workout['plannedWorkoutId'], {
      'performedAt': DateTime.now().toUtc().subtract(const Duration(hours: 1)).toIso8601String(),
      'sessionRpe': 6,
      'exercises': [for (final e in exercises(workout)) {...prescribedResult(e), 'plannedExerciseId': e['plannedExerciseId']}],
    });
    for (final e in exercises(workout).where(timed)) {
      final row = exerciseOf(reported, e['plannedExerciseId']);
      expect(row['actualDurationSeconds'], plannedTotal(e));
      expect(pct(row), 100);
    }
    expect((reported['completionPercentage'] as num).toDouble(), 100);
    // ignore: avoid_print
    print('REPORTE workout=${workout['plannedWorkoutId']}: ${exercises(workout).where(timed).map((e) => '${e['plannedSets']}x${e['plannedDurationSeconds']}=${plannedTotal(e)}s').join(', ')} → sesión ${reported['completionPercentage']} %');
  }, skip: base == null ? 'KORA_LIVE_API_BASE_URL not set (needs a running backend)' : false);
}
